import { InvalidTransitionError, ValidationError } from '../errors/DomainError';
import { OrderLine } from './OrderLine';
import { FulfilmentStatus, OrderStatus, isCancellable, nextStatus } from './OrderStatus';

/** Aggregate root for a customer order and its fulfilment lifecycle. */
export class Order {
  private constructor(
    readonly id: string,
    readonly customerId: string,
    readonly lines: readonly OrderLine[],
    readonly placedAt: Date,
    private currentStatus: OrderStatus,
  ) {}

  static place(id: string, customerId: string, lines: readonly OrderLine[], placedAt: Date): Order {
    if (customerId.trim() === '') {
      throw new ValidationError('Customer id must not be empty');
    }
    if (lines.length === 0) {
      throw new ValidationError('An order must contain at least one line');
    }
    return new Order(id, customerId, OrderLine.consolidate(lines), placedAt, 'placed');
  }

  get status(): OrderStatus {
    return this.currentStatus;
  }

  /** Moves the order to the target status, which must be the immediate next step. */
  advanceTo(target: FulfilmentStatus): void {
    if (nextStatus(this.currentStatus) !== target) {
      throw new InvalidTransitionError(this.currentStatus, target);
    }
    this.currentStatus = target;
  }

  /** Cancels the order; only allowed before it has shipped. */
  cancel(): void {
    if (!isCancellable(this.currentStatus)) {
      throw new InvalidTransitionError(this.currentStatus, 'cancelled');
    }
    this.currentStatus = 'cancelled';
  }
}

